function navMark(){ var y=window.scrollY||0; if(NAVK) NAVS[NAVK]=y; var s=history.state, rev=!!(s&&s.matk), k=rev?s.matk:('k'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)); if(!rev){ try{ history.replaceState({matk:k},''); }catch(e){} } NAVK=k; return rev&&NAVS[k]>0?NAVS[k]:0; }
